) ?>" <?= $filters['sort'] === $value ? 'selected' : '' ?>><?= $e($label) ?></option><?php endforeach; ?></select></label><button class="button">Apply filters ↗</button></form></aside><section><div class="collection-toolbar"><span><?= $e($products['total']) ?> materials</span><span>Page <?= $e($products['page']) ?> of <?= $e(max(1, $products['pages'])) ?></span></div>
